#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int *items;
    size_t len, cap;
} IntList;                                    /* owner of items. */

bool list_push(IntList *l, int value) {
    if (l->len == l->cap) {
        size_t new_cap = l->cap ? l->cap * 2 : 4;
        if (new_cap > SIZE_MAX / sizeof *l->items) return false;   /* overflow guard. */
        int *tmp = realloc(l->items, new_cap * sizeof *l->items);
        if (tmp == NULL) return false;         /* old block still valid and owned. */
        l->items = tmp;
        l->cap = new_cap;
    }
    l->items[l->len++] = value;
    return true;
}

void list_free(IntList *l) {
    free(l->items);                            /* exactly once. */
    l->items = NULL;                           /* a second free(NULL) is harmless. */
    l->len = l->cap = 0;
}
